   (src_clk,
    src_in_bin,
    dest_clk,
    dest_out_bin);
  input src_clk;
  input [14:0]src_in_bin;
  input dest_clk;
  output [14:0]dest_out_bin;

  wire [14:0]async_path;
  wire [13:0]binval;
